const state = $input.first().json;
const guest = $('Validate Token').first().json;

// 1. Party must be ready
if (!state.party_can_pay) {
  throw new Error('Party not ready: items still unclaimed or subtotal not covered');
}

// 2. Compute guest totals
const partySubtotal  = Number(state.party_subtotal);
const tipPct         = Number(state.tip_percent);
const partyTipCents  = Math.round(partySubtotal * tipPct / 100);
const guestSubtotal  = Number(state.guest_subtotal_cents);
const guestTip       = partySubtotal > 0
  ? Math.round((guestSubtotal / partySubtotal) * partyTipCents)
  : 0;
const guestTotalDue  = guestSubtotal + guestTip;
const amountPaid     = Number(state.amount_paid_cents);

// 3. Verify payment covers total
if (amountPaid < guestTotalDue) {
  throw new Error(`Payment (${amountPaid}) is less than total due (${guestTotalDue})`);
}

return [{
  json: {
    guest_id:          guest.guest_id,
    party_id:          guest.party_id,
    user_id:           guest.user_id,
    restaurant_name:   state.restaurant_name,
    subtotal_cents:    guestSubtotal,
    tip_cents:         guestTip,
    total_cents:       guestTotalDue,
    paid_cents:        amountPaid
  }
}];

