-- Update restaurant analytics (only for logged-in users)
DO $$
DECLARE
  v_user_id    UUID := $1::uuid;
  v_rest_name  TEXT := $2;
  v_rest_id    UUID;
BEGIN
  IF v_user_id IS NULL OR v_rest_name IS NULL THEN RETURN; END IF;
  INSERT INTO restaurants (name) VALUES (v_rest_name) ON CONFLICT (name) DO NOTHING;
  SELECT id INTO v_rest_id FROM restaurants WHERE name = v_rest_name;
  INSERT INTO user_restaurant_history (user_id, restaurant_id, visit_count, last_visit_at)
  VALUES (v_user_id, v_rest_id, 1, NOW())
  ON CONFLICT (user_id, restaurant_id) DO UPDATE
    SET visit_count   = user_restaurant_history.visit_count + 1,
        last_visit_at = NOW();
END $$

